{
  "name": "mcp-subagents-opencode",
  "version": "1.2.5",
  "description": "MCP server for spawning and managing OpenCode AI sub-agents — parallel task execution with planner, coder, researcher & tester specialists",
  "type": "module",
  "main": "build/index.js",
  "bin": {
    "mcp-subagents-opencode": "build/index.js"
  },
  "files": [
    "build",
    "README.md",
    "LICENSE"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/yigitkonur/mcp-subagents-opencode.git"
  },
  "homepage": "https://github.com/yigitkonur/mcp-subagents-opencode#readme",
  "bugs": {
    "url": "https://github.com/yigitkonur/mcp-subagents-opencode/issues"
  },
  "author": "Yigit Konur <yigit35@gmail.com>",
  "keywords": [
    "mcp",
    "opencode",
    "agent",
    "ai",
    "sub-agents",
    "model-context-protocol",
    "claude",
    "anthropic",
    "parallel",
    "autonomous",
    "coding-agent",
    "ai-agents"
  ],
  "license": "MIT",
  "dependencies": {
    "@modelcontextprotocol/sdk": "^1.25.0",
    "unique-names-generator": "^4.7.1",
    "zod": "^3.23.0"
  },
  "devDependencies": {
    "@types/node": "^22.10.5",
    "tsx": "^4.19.2",
    "typescript": "^5.7.2"
  },
  "engines": {
    "node": ">=18.0.0"
  },
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "build": "tsc --noEmitOnError false; cp src/templates/*.mdx build/templates/; mkdir -p build/templates/overlays && cp src/templates/overlays/*.mdx build/templates/overlays/",
    "dev": "tsx watch src/index.ts",
    "start": "node build/index.js",
    "clean": "rm -rf build"
  }
}
